+    fy += __shfl_down_sync(mask, fy, 2);
+    fz += __shfl_down_sync(mask, fz, 2);
+    fx += __shfl_down_sync(mask, fx, 1);
+    fy += __shfl_down_sync(mask, fy, 1);
+    fz += __shfl_down_sync(mask, fz, 1);

-    p.x += p.vx * dt;
-    p.y += p.vy * dt;
-    p.z += p.vz * dt;
-
-    out[i] = p;
